{
  "id": "LIU-INPUT-REPAIRED",
  "revision": 2,
  "engine": "human-curated-from-claude-p1-and-qwen-p1",
  "source_status": "Liu arXiv:2509.02950v1 is unrefereed; only the M_{5,8} half is used",
  "liu_sha256": "ada191f5012a45d57640ef4333c6e64e218babdb22aee4579110e5d1f0c66d5a",
  "theorem": "Over C with Q coefficients: A^*(M_{5,8})=R^*(M_{5,8}), M_{5,8} has CKgP, W_24 H^{24}(M_{5,8};Q)=0, and W_{-16} H^{BM}_{16}(M_{5,8};Q)=0.",
  "claims": [
    {
      "id": "L1",
      "status": "proposed",
      "statement": "Over C, A^*(U_8) is tautological and U_8 has CKgP, after descent from the mu_5-gerbe M'_{5,8} by Canning-Larson Lemma 3.6."
    },
    {
      "id": "L2",
      "status": "proposed",
      "statement": "On M_{5,8} minus M^3_{5,8}, the class [M_omega] is tautological of expected Porteous codimension 4. Lower-gonality degeneracy components on the compactification have higher codimension and do not affect this class."
    },
    {
      "id": "L3",
      "status": "proposed",
      "statement": "Normalized sequence (10) gives c(G)=c(L^vee tensor f_* omega_f); with c_1(L)=2 psi_i on M_omega this proves Liu Corollary 3.6."
    },
    {
      "id": "L4",
      "status": "proposed",
      "statement": "The load-bearing fact is that BGL_4 -> BG is a representable A^4-bundle; Canning-Larson Lemma 3.5 then gives CKgP of BG from CKgP of BGL_4. Liu's ordinary Chow-ring isomorphism is not enough."
    },
    {
      "id": "L5",
      "status": "proposed",
      "statement": "Liu Proposition 3.3 is an open immersion of stacks: over G(3,E) the universal net cuts out a relative complete intersection C, C cap PF is finite flat of degree 8 on an open, and p_8 is the residual degree-1 section after removing the seven given sections."
    },
    {
      "id": "L6",
      "status": "proposed",
      "statement": "A^*(M_omega) is generated by restrictions of tautological classes, and M_omega has CKgP. Liu Lemma 3.8 should be read as -psi_i, not 3 psi_i."
    },
    {
      "id": "L7",
      "status": "proposed",
      "statement": "Canning-Larson Lemma 9.9 applies at g=5, n=8 (n=8 <= g+7=12) and supplies CKgP of M^3_{5,8} together with tautologicality of classes supported on it."
    },
    {
      "id": "L8",
      "status": "proposed",
      "statement": "Excision and Canning-Larson Lemma 3.4 glue L1, L6, L7 to A^*(M_{5,8})=R^*(M_{5,8}) and CKgP of M_{5,8}."
    },
    {
      "id": "L9",
      "status": "proposed",
      "statement": "CLP Lemma 4.3 identifies W_24 H^{24} with the cycle-class image of A^{12}=R^{12}. Ionel Theorem 0.1 kills that cohomological image at degree 12; Chow vanishing of R^{12} is not used."
    },
    {
      "id": "L10",
      "status": "proposed",
      "statement": "dim M_{5,8}=20 and H^{BM}_{16} cong H^{24}(20) give W_{-16} H^{BM}_{16}(M_{5,8};Q)=0."
    }
  ]
}
